pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = 0x0000000000000000000000000000000000000001;
        address other = 0x0000000000000000000000000000000000000002;
        address target = 0x0000000000000000000000000000000000000003;

        // First owner sends 1 wei via Command to target (just a call)
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        c.Command{value: 1 wei}(target, "");

        // Now someone else calls multiplicate with 2 wei
        vm.deal(other, 1 ether);
        vm.prank(other);
        c.multiplicate{value: 2 wei}(target);

        // In reference: multiplicate sends (balance+msg.value)=3 wei to target, contract balance becomes 0
        // In buggy: multiplicate sends 3 wei to target (same), but withdraw check removed doesn't affect this
        // But buggy withdraw allows anyone to drain, so if someone calls withdraw contract balance goes 0
        // Actually difference: reference withdraw requires owner, buggy doesn't

        // Reset state: have non-owner try withdraw on reference (would revert)
        // Let's just check that after multiplicate, reference has 0 balance, buggy also 0
        // Need a scenario where they diverge on balance

        // Clear: owner calls Command with 5 wei, then non-owner calls withdraw:
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        c.Command{value: 5 wei}(target, "");

        // Non-owner tries withdraw
        vm.prank(other);
        // In reference: withdraw reverts (require owner), so balance stays 5 wei
        // In buggy: withdraw succeeds, sends 5 wei to owner, balance becomes 0

        bool success;
        try c.withdraw() {
            success = true;
        } catch {
            success = false;
        }

        // After non-owner call: reference balance = 5 wei (revert), buggy balance = 0 wei (success)
        // But we can't easily compare in try/catch because we need to know which contract we have
        // Actually we can: if withdraw succeeded, then balance=0 and assert on balance
        // If it reverted, then balance=5

        vm.prank(other);
        try c.withdraw() {
            // Buggy version: withdraw succeeded, balance should be 0
            assertTrue(address(c).balance == 0 wei);
        } catch {
            // Reference version: withdraw reverted, balance should still be 5 wei
            assertTrue(address(c).balance == 5 wei);
        }
    }
}

